import { iconMarkup } from '@/lib/publish/contract'
import type { HbIcons } from './types'

/** The studio's inline markers (its lib/renderer/inline.ts). Escaped first, then marked up, so text cannot inject HTML. */
const INKS = ['blue', 'red', 'green', 'black', 'purple', 'orange', 'pink']
const INK_RE = new RegExp(`\\{(${INKS.join('|')}):([^{}\\n]+?)\\}`, 'g')
const ICON_RE = /\{icon:([^{}\n]+?)\}/g
const MARKERS: [RegExp, string][] = [
  [/==((?:[^=\n]|=(?!=))+?)==/g, '<mark>$1</mark>'],
  [/\*\*([^*\n]+?)\*\*/g, '<b>$1</b>'],
  [/__([^_\n]+?)__/g, '<u>$1</u>'],
  [INK_RE, '<span class="ink-$1">$2</span>'],
]

const escapeHtml = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;')

function splitCode(s: string) {
  const codes: string[] = []
  const text = s.replace(/`([^`\n]+?)`/g, (_, inner: string) => `\u0000${codes.push(inner) - 1}\u0000`)
  return { text, codes }
}

export function renderInline(s: string, icons: HbIcons = {}): string {
  const { text, codes } = splitCode(escapeHtml(s))
  let out = text
  for (const [re, rep] of MARKERS) out = out.replace(re, rep)
  out = out.replace(ICON_RE, (_, name: string) => {
    const svg = iconMarkup(icons, name.trim())
    return svg ? `<span class="icon" aria-hidden="true">${svg}</span>` : ''
  })
  return out.replace(/\u0000(\d+)\u0000/g, (_, i: string) => `<code>${codes[Number(i)]}</code>`)
}

export function stripInline(s: string): string {
  const { text, codes } = splitCode(s)
  let out = text
  for (const [re, rep] of MARKERS) out = out.replace(re, rep.includes('$2') ? '$2' : '$1').replace(/<[^>]+>/g, '')
  out = out.replace(ICON_RE, '').replace(/ {2,}/g, ' ').trim()
  return out.replace(/\u0000(\d+)\u0000/g, (_, i: string) => codes[Number(i)])
}
